import{_ as t,o,c as a,ag as r}from"./chunks/framework.CrXGS008.js";const g=JSON.parse('{"title":"Stations","description":"","frontmatter":{},"headers":[],"relativePath":"fr/repair-station/stations.md","filePath":"fr/repair-station/stations.md"}'),s={name:"fr/repair-station/stations.md"};function i(n,e,l,u,c,d){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="stations" tabindex="-1">Stations <a class="header-anchor" href="#stations" aria-label="Permalink to &quot;Stations&quot;">​</a></h1><p>Une station est une zone d&#39;arrêt pour les véhicules, avec un rayon, un pourcentage de prix et, si vous le voulez, un prop comme un coffre à outils posé à côté. Trois stations sont prêtes d&#39;office : <strong>Hayes Autos</strong>, <strong>Sandy Shores</strong> et <strong>Paleto Bay</strong>.</p><h2 id="le-deroulement-d-une-reparation" tabindex="-1">Le déroulement d&#39;une réparation <a class="header-anchor" href="#le-deroulement-d-une-reparation" aria-label="Permalink to &quot;Le déroulement d&#39;une réparation&quot;">​</a></h2><ol><li>Le conducteur s&#39;arrête dans le rayon de la station. Une invite affiche le prix le plus bas.</li><li><strong>E</strong> ouvre le menu de réparation avec les dégâts du véhicule et les prestations, avec leurs prix (remises par métier et pourcentage de la station compris).</li><li>Le prix est payé, le moteur s&#39;éteint et le capot s&#39;ouvre. Une barre de progression tourne pendant la durée de la prestation, avec le son et les étincelles. Appuyez sur <strong>X</strong> pour annuler.</li><li>À la fin, les parties réparées sont remises à neuf et le véhicule peut repartir.</li></ol><p>La station refuse la réparation quand :</p><ul><li>la station est fermée, ou <code>Enabled</code> est désactivé ;</li><li>le joueur ne conduit pas le véhicule, ou le véhicule n&#39;est pas dans la zone de la station ;</li><li>le véhicule roule ;</li><li>la station est déjà utilisée (un véhicule à la fois) ;</li><li>la classe du véhicule est refusée (<code>BlockedClasses</code>) ;</li><li>la prestation ne répare rien sur ce véhicule et <code>RequireDamage</code> est activé ;</li><li>le joueur doit attendre la fin du délai (<code>CooldownSeconds</code>) ;</li><li>des mécaniciens sont en service, voir plus bas ;</li><li>le joueur ne peut pas payer.</li></ul><p>Si le joueur quitte le véhicule, s&#39;éloigne ou annule, ou si la station est fermée ou supprimée pendant la réparation, la réparation s&#39;arrête et le joueur est remboursé du montant débité, sur le compte débité.</p><h2 id="mecaniciens-en-service" tabindex="-1">Mécaniciens en service <a class="header-anchor" href="#mecaniciens-en-service" aria-label="Permalink to &quot;Mécaniciens en service&quot;">​</a></h2><p>Les joueurs qui tiennent un garage ne doivent pas perdre leurs clients au profit d&#39;une station. Listez leurs métiers dans <code>MechanicJobs</code> et réglez <code>MaxMechanicsOnDuty</code> : tant que ce nombre de mécaniciens ou plus est en service, toutes les stations sont fermées et invitent les joueurs à les appeler. Avec <code>0</code>, les stations ne ferment jamais pour cette raison.</p><h2 id="l-editeur-de-stations" tabindex="-1">L&#39;éditeur de stations <a class="header-anchor" href="#l-editeur-de-stations" aria-label="Permalink to &quot;L&#39;éditeur de stations&quot;">​</a></h2><p>Ouvrez-le avec <code>/nay:repair</code>, ou avec <strong>Gérer les stations</strong> sur la page Repair Station de <code>/nay</code>. Il demande le scope <code>nay_repair.config</code>.</p><ol><li><strong>Nouvelle station ici</strong> : placez-vous là où les véhicules doivent s&#39;arrêter, dans votre véhicule ou à pied. La station prend votre position et votre orientation.</li><li>Choisissez la position du véhicule (<strong>Arrêt du véhicule</strong>) ou celle du prop (<strong>Prop</strong>), ou appuyez sur Tab, et déplacez-la : <ul><li>flèches : avant, arrière, gauche, droite, selon la caméra ;</li><li>Page Up / Page Down : hauteur ;</li><li>Q / E : rotation ;</li><li>Maj : pas fins.</li><li>G : se déplacer à pied (<strong>Se déplacer</strong>), et G de nouveau pour revenir au panneau.</li></ul></li><li><strong>À ma position</strong> et <strong>Au sol</strong> placent l&#39;élément sélectionné.</li><li>Réglez le nom, le rayon, le pourcentage de prix, le blip et le prop. Props suggérés : <code>prop_toolchest_05</code>, <code>prop_toolchest_01</code>, <code>prop_carcreeper</code>, <code>prop_compressor_03</code>, ou n&#39;importe quel nom de modèle.</li><li><strong>Entrée</strong> enregistre, même pendant la saisie dans un champ, <strong>Retour arrière</strong> ou <strong>Échap</strong> annule. La station est active tout de suite pour tous les joueurs.</li></ol><p>Le gestionnaire permet aussi d&#39;aller à une station, de l&#39;ouvrir ou de la fermer, et de la supprimer (appuyez deux fois pour confirmer). L&#39;éditeur remplit le réglage <code>Stations</code>, décrit sur la page <a href="/fr/repair-station/settings#stations">Réglages</a>. Chaque station reçoit un identifiant qui ne change jamais.</p>',13)])])}const m=t(s,[["render",i]]);export{g as __pageData,m as default};
